<?php declare(strict_types=1); $isEdit = $selectedAdminClub !== null; ?>
<section class="view hidden" id="view-admin-club-form" data-title="<?= $isEdit ? 'Edit club' : 'Create club' ?>" data-section="Administration">
<button class="back-link" data-view="admin-clubs">← Back to clubs</button><div class="form-heading"><div><span class="eyebrow gold-eyebrow"><?= $isEdit ? 'EDIT CLUB' : 'NEW CLUB' ?></span><h1><?= $isEdit ? 'Edit a club' : 'Create a club' ?></h1><p class="muted"><?= $isEdit ? 'Update this community in the ClubConnect directory.' : 'Add a new community to the ClubConnect directory.' ?></p></div></div>
<form class="panel admin-form validate-form" data-server-form="true" method="post" action="index.php?action=<?= $isEdit ? 'update-club' : 'create-club' ?>"><input type="hidden" name="_csrf" value="<?= e(\ClubConnect\Config\Csrf::token()) ?>"><?php if ($isEdit): ?><input type="hidden" name="id" value="<?= (int) $selectedAdminClub['club_id'] ?>"><?php endif; ?><div class="form-section"><h2>Basic information</h2><div class="form-grid"><div class="field-span"><label for="club-name">Club name</label><input id="club-name" name="name" type="text" value="<?= e($selectedAdminClub['name'] ?? '') ?>" maxlength="150" required></div><div><label for="club-category">Category</label><select id="club-category" name="category" required><option value="">Select a category</option><?php foreach (['Academic', 'Creative', 'Social', 'Sports'] as $category): ?><option <?= strtolower((string) ($selectedAdminClub['category'] ?? '')) === strtolower($category) ? 'selected' : '' ?>><?= e($category) ?></option><?php endforeach; ?></select></div><div><label for="club-contact-email">Contact email</label><input id="club-contact-email" name="contact_email" type="email" value="<?= e($selectedAdminClub['contact_email'] ?? '') ?>"></div><div class="field-span"><label for="club-description">Description</label><textarea id="club-description" name="description" rows="4" maxlength="5000" required><?= e($selectedAdminClub['description'] ?? '') ?></textarea></div></div></div><div class="form-actions"><button class="button button-outline" type="button" data-view="admin-clubs">Cancel</button><button class="button button-dark" type="submit"><?= $isEdit ? 'Update club' : 'Save club' ?> <span>→</span></button></div></form>
</section>
